// Rows come from the Postgres node, one item per week, oldest first.
const rows = $input.all().map((item) => item.json);
if (rows.length === 0) throw new Error('The query returned no rows, so there is nothing to chart.');

const weeks = rows.map((r) => String(r.week));
// Number(null) and Number('') are 0, so a missing figure has to be caught before Number().
const bad = (v) => v == null || String(v).trim() === '' || !Number.isFinite(Number(v));
const badRow = rows.findIndex((r) => bad(r.orders) || bad(r.revenue));
if (badRow !== -1) {
  throw new Error('Row ' + (badRow + 1) + ' (week ' + weeks[badRow] + ') has no number in orders or revenue. Every row needs numeric orders and revenue columns.');
}
const orders = rows.map((r) => Number(r.orders));
const revenue = rows.map((r) => Number(r.revenue));

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const money = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

const chart = {
  type: 'bar',
  data: { labels: weeks, datasets: [{ label: 'Revenue', data: revenue }] },
  options: { plugins: { title: { display: true, text: 'Revenue by week' }, chartpng: { source: 'Source: orders table' } } },
};
const imageUrl = 'https://chartpng.dev/chart?w=800&h=450&dpr=2&c=' + encodeURIComponent(JSON.stringify(chart));

const last = revenue.length - 1;
let summary = 'Week of ' + weeks[last] + ': ' + money(revenue[last]) + ' revenue from ' + orders[last] + ' orders.';
if (last > 0 && revenue[last - 1] > 0) {
  const pct = ((revenue[last] - revenue[last - 1]) / revenue[last - 1]) * 100;
  summary += ' ' + (pct >= 0 ? 'Up ' : 'Down ') + Math.abs(pct).toFixed(1) + '% on the week before.';
}
const alt = 'Bar chart of revenue by week, ' + rows.length + ' weeks. ' + summary;

// The same numbers as text, for mail clients that block remote images.
const cell = 'padding:4px 12px;border-bottom:1px solid #dddddd;';
const tableHtml = rows
  .map((r, i) => '<tr><td style="' + cell + '">' + esc(weeks[i]) + '</td><td style="' + cell + 'text-align:right">' + orders[i] + '</td><td style="' + cell + 'text-align:right">' + money(revenue[i]) + '</td></tr>')
  .join('');

return [{ json: { chart, imageUrl, alt: esc(alt), summary: esc(summary), tableHtml } }];
